/** App version from package.json, injected by vite.config.ts. */
declare const __APP_VERSION__: string;
/** The home page's address (vite.config.ts): the local one in dev. */
declare const __HOME_URL__: string;
/** Short hash of the game data files (vite.config.ts), added to their URLs as `?v=`; "" when the build has none, "dev" in dev. */
declare const __GAME_VERSION__: string;
